-- Struct
select @ngay_ct as ngay_ct, @dien_giai as dien_giai, @ma_quyen as ma_nk, @ma_nghiep_vu as ma_nghiep_vu, @ma_kh as ma_kh
		, @tk_no as tk_no, @tk_co as tk_co, @ma_vv as ma_vv, @tien_nt as tien_nt, @s2 as s2, @ma_dtqt as ma_td1, @stt_uu_tien as crm_uu_tien0
		, @status as status, @ma_dvcs as ma_dvcs, @crm_ma_dat_cho as crm_ma_dat_cho, @fcode4 as fcode4
		, 1 as stt
	into #datatmp

declare @field varchar(64), @message nvarchar(512)
exec zrs_Posting$Post2GL$Checking 'BC1', @ma_dvcs, @ngay_ct, 1, @field out, @message out, @@language, @@userID, @@admin, '@@sysDatabaseName'
if isnull(@message, '') <> '' begin
	select @field as field, @message as message, '' as script
	return
end

exec dbo.zrs_createBC1 @@sysDatabaseName, @@userID

select '' as field, '' as message, 'on$&Identity;$QueryComplete(this);' as script
return







			&OutlineEntry;

function load$&Identity;$(f) {
	var g = f.grid;

	f.add_onResponseComplete(on$&Identity;$ResponseComplete);
	f._looking = f.getItem('ma_quyen')._controlBehavior;
	f._looking.add_loading(on$&Identity;$Before$Loading);
	f.setItemValues('ma_kh, ten_kh%l, ma_vv, stt_uu_tien, ma_dtqt, crm_ma_dat_cho', [g._ma_kh, g._ten_kh, g._ma_sp, g._stt_uu_tien, g._ma_san, g._ma_dat_cho]);
	f.setReferenceKeyFilter('ma_nghiep_vu');

	f.request('ValueDefault', 'ValueDefault', ['ma_dvcs', 'ma_vv', 'ma_kh', 'ma_dtqt', 'crm_ma_dat_cho']);
	f.getItem('ngay_ct').focus();
	&descGenerateScriptLoading;
}
function dispose$&Identity;$(f) {
	try {f._looking.remove_loading(on$&Identity;$Before$Loading);

	} catch (ex) {

	console.log('ex', ex);
	}
	try {f.remove_onResponseComplete(on$&Identity;$ResponseComplete);} catch (ex) {}
}
function on$&Identity;$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'ValueDefault':
			f.setItemValues('ma_dvcs, ngay_ct, ma_quyen, ten_quyen%l, ma_nghiep_vu, ten_nghiep_vu%l, s2, tk_no, ten_tk_no%l, tk_co, ten_tk_co%l, ten_vv%l, ten_dtqt%l, tien_nt'
					, [result[0].Value, result[1].Value, result[2].Value, result[3].Value, result[4].Value, result[5].Value, result[6].Value, result[7].Value, result[8].Value, result[9].Value, result[10].Value, result[11].Value, result[12].Value, result[13].Value]);
			f.setReferenceKeyFilter('fcode4');
			f.request('DateChange', 'DateChange', ['ma_dvcs', 'ngay_ct'], null);
			break;
		case 'BussinessCode':
					f.setItemValues('s2, tk_no, ten_tk_no%l, tk_co, ten_tk_co%l'
					, [result[2].Value, result[3].Value, result[4].Value, result[5].Value, result[6].Value]);
			break;
		case 'DateChange':
			f.setItemValues('ma_quyen, ten_quyen%l',[result[0].Value, result[1].Value]);
			break;
		case 'descGenerate':
			if (result && result.length > 0) f.setItemValue('dien_giai', result[0][1]);
			break;
		default:
			break;
	}
}



function on$&Identity;$Before$Loading(sender, e) {
	var f = sender._element.parentForm;
	console.log('1', 1);
	if (!f.validFields('ngay_ct')) e.type.cancelEvent = true;
	else {
		var g = f.grid;
		a = [
			{Name: 'd', Type: 'DateTime', Value: f.getItemValue('ngay_ct')},
			{Name: 'u', Type: 'String', Value: f.getItemValue('ma_dvcs')},
			{Name: 'c', Type: 'String', Value: 'BC1'}
		];
		sender.set_memvars(a);
	}
}
function on$&Identity;$QueryComplete(f) {
	var g = f.grid;
	g._formScript = 'show$&Identity;$QueryComplete(this)';
}
function onChange$&Identity;$Date(o) {
		var f = o.parentForm;
		if (!f.validFields('ngay_ct')) return;

		var a = [
				{Name: 'd', Type: 'DateTime', Value: f.getItemValue('ngay_ct')},
				{Name: 'u', Type: 'String', Value: f.getItemValue('ma_dvcs')},
				{Name: 'c', Type: 'String', Value: 'BC1'}
		];
		f._looking.set_memvars(a);

		f.setItemValues('ma_quyen, ten_quyen%l', ['', '']);
		f.request('DateChange', 'DateChange', ['ma_dvcs', 'ngay_ct'], null);
}

function show$&Identity;$QueryComplete(g) {
	var v = (g._language == 'v'), id = g.get_id();
	var e = (v ? 'Chương trình đã thực hiện xong.' : 'The process was completed successfully.');
	$message.show(e, String.format('$find(\'{0}\')._focusWhenTabChanged();', id));
	g._focusWhenTabChanged();
	g.goToPage(-1);
}

function onChange$&Identity;$Account(o){
	var f = o.parentForm;
	f.setReferenceKeyFilter('fcode4');
}

function onChange$&Identity;$BussinessCode(o) {
	var f = o.parentForm;
	f.request('BussinessCode', 'BussinessCode', ['ma_nghiep_vu'], o);
}




function descGenerate(f) {
	if (f._action == 'View') return;
	f.request('descGenerate', 'descGenerate', ['crm_ma_dat_cho', 'ma_vv', 'ma_dtqt', 'ma_nghiep_vu', 'stt_uu_tien'], null);
}

			&descGenerateScript;








				declare @d smalldatetime = convert(char(8), getdate(), 112), @u varchar(33) = @ma_dvcs, @c varchar(3) = 'BC1', @z_ma_nghiep_vu1 varchar(33)
								, @ten_vv nvarchar(256), @ten_dtqt1 nvarchar(256)

				select top 1 rtrim(ma_nk) as ma_quyen, rtrim(ten_nk%l) as ten_quyen%l into #q from v20dmnk where ((ma_dvcs = '') or (ma_dvcs = @u)) and ((@d >= ngay_hl_tu or ngay_hl_tu is null) and (@d <= ngay_hl_den or ngay_hl_den is null)) 
					and ma_nk in (select ma_nk from v20dmctnk where ma_ct = @c and (lstuser = '' or charindex(rtrim(@@userName) + ',', replace(lstuser, ' ', '') + ',') > 0)) and status = '1'

				if not exists(select 1 from #q) insert into #q select '', ''

				select @z_ma_nghiep_vu1 = rtrim(val) from options where name = 'z_ma_nghiep_vu1'

				select top 1 rtrim(ma_nv) as ma_nv, rtrim(ten_nv%l) as ten_nv%l, ma_loai_tc
						into #n from zdmnvnd where (ma_ct = '' or ma_ct = @c) and (ma_dvcs = '' or ma_dvcs = @u) and status = '1' and ma_nv = @z_ma_nghiep_vu1
				if not exists(select 1 from #n) insert into #n select '', '', ''

				select top 1 rtrim(a.tk_no) as tk_no, t1.ten_tk as ten_tk_no, rtrim(a.tk_co) as tk_co, t2.ten_tk as ten_tk_co
						into #d from zdmnvndd a 
							left join dmtk t1 with(nolock) on a.tk_no = t1.tk
							left join dmtk t2 with(nolock) on a.tk_co = t2.tk
								where a.ma_nv = @z_ma_nghiep_vu1
				if not exists(select 1 from #d) insert into #d select '', ''

				select @ten_vv = ten_vv from dmvv with(nolock) where ma_vv = @ma_vv
				select @ten_dtqt1 = ten_dtqt from dmdtqt1 with(nolock) where ma_dtqt = @ma_dtqt

				--Tiền còn lại
				declare @tien_da_thu numeric(19,4), @tien_nt numeric(19,4)
				select @tien_da_thu = sum(tien) from _crdatcho where ma_dat_cho = @crm_ma_dat_cho 
				select @tien_nt = tong_tien - isnull(@tien_da_thu, 0) from dm_dat_cho where ma_dat_cho = @crm_ma_dat_cho
				select top 1 @@unit as ma_dvcs, @d as ngay_ct, a.*, b.*, d.*, @ten_vv as ten_vv, @ten_dtqt1 as ten_dtqt1, @tien_nt as tien_nt
						from #q a, #n b, #d d
				return







if exists(select 1 from zdmnvnd where ma_nv = @ma_nghiep_vu) begin
	select top 1 rtrim(a.ma_nv) as ma_nv, rtrim(a.ten_nv%l) as ten_nv%l, a.ma_loai_tc
			, rtrim(b.tk_no) as tk_no, t1.ten_tk as ten_tk_no, rtrim(b.tk_co) as tk_co, t2.ten_tk as ten_tk_co
			from zdmnvnd a 
				left join zdmnvndd b on a.ma_nv = b.ma_nv
				left join dmtk t1 with(nolock) on b.tk_no = t1.tk
				left join dmtk t2 with(nolock) on b.tk_co = t2.tk
			where a.ma_nv = @ma_nghiep_vu
	return
end






				declare @u varchar(33) = @ma_dvcs, @c varchar(3) = 'BC1', @d smalldatetime = @ngay_ct

				select top 1 rtrim(ma_nk) as ma_quyen, rtrim(ten_nk%l) as [ten_quyen%l]
				from v20dmnk 
				where ((ma_dvcs = '') or (ma_dvcs = @u)) 
					and ((@d >= ngay_hl_tu or ngay_hl_tu is null) and (@d <= ngay_hl_den or ngay_hl_den is null)) 
					and ma_nk in (
							select ma_nk from v20dmctnk 
							where ma_ct = @c 
								and (lstuser = '' or charindex(rtrim(@@userName) + ',', replace(lstuser, ' ', '') + ',') > 0)
					) 
					and status = '1'

				if @@rowcount = 0 select '' as ma_quyen, '' as [ten_quyen%l]
				return









				Declare @dien_giai_h nvarchar(512)
				select stt_rec, ma_dat_cho into #datcho$tt from _crdatcho a where ma_dat_cho = @crm_ma_dat_cho

				select cast('' as nvarchar(512)) dien_giai into #d46 

				update #d46 set dien_giai = ten_nv from zdmnvnd where @ma_nghiep_vu = ma_nv

					update #d46 set dien_giai = case when exists(select 1 from #datcho$tt where ma_dat_cho = @crm_ma_dat_cho) then N' thu bổ sung ' else '' end
					+ rtrim(a.dien_giai) + N' ' + case when g.ma_vv_rg <> '' THEN RTRIM(g.ma_vv_rg) else '...' end
					+ '.' + case when b.ma_vv_rg <> '' THEN RTRIM(b.ma_vv_rg) else '...' end + '/'
					+ isnull(h.ten_loai_sp,'') + '-' + cast(isnull(@stt_uu_tien,0) as varchar(2)) 
					+ '/'+ rtrim(isnull(f.ten_dtqt,'')) 
						from #d46 a 
						left join dmvv b on @ma_vv = b.ma_vv 
						left join dmnhvv d on b.nh_vv1 = d.ma_nh
						LEFT JOIN dm_dat_cho e on @crm_ma_dat_cho = e.ma_dat_cho
						LEFT JOIn dmdtqt1 f on @ma_dtqt = f.ma_dtqt
						left join dmvv g on b.nh_vv1 = g.ma_vv
						left join zdmloaisp h on b.loai_sp = h.loai_sp

				set @dien_giai_h = ''
				select @dien_giai_h = @dien_giai_h 
---				+ case when @dien_giai_h = '' then '' else ', ' end + rtrim(c.ten_dot)
---					from #d46 a join dmtthd c on a.s1 = c.ma_dot order by line_nbr

				select top 1 @dien_giai_h = dien_giai + case when @dien_giai_h <> '' then N' đợt ' + @dien_giai_h else '' end from #d46 where dien_giai <> ''

					if exists(select 1 from #d46 where dien_giai <> '') begin
						select '' as array$, dien_giai from #d46 where dien_giai <> '' 
						return
				END








